let qr = null
async function initQRCodeInstance() {
  if (qr) return qr
  const qrcode = (
    await import(
      /* webpackChunkName: "qrcode" */
      'qrcode'
    )
  ).default
  qr = {
    toCanvas: (text, options) => {
      return new Promise((resolve, reject) =>
        qrcode.toCanvas(text, options, (error, canvas) =>
          error ? reject(error) : resolve(canvas),
        ),
      )
    },
    toPNG: (text, options) =>
      qrcode.toDataURL(text, {
        type: 'image/png',
        ...options,
      }),
  }
  return qr
}
async function generateQRCode({text, logo, logoSize = '0.2'}, options) {
  const {toCanvas, toPNG} = await initQRCodeInstance()
  const segments = [
    {
      data: new TextEncoder().encode(text),
      mode: 'byte',
    },
  ]
  const qrWidth = options.width
  if (logo) {
    const level = options.errorCorrectionLevel ?? 'H'
    options.errorCorrectionLevel =
      level.length === 1
        ? level.toUpperCase()
        : `${level[0].toUpperCase()}${level[1].toLowerCase()}`
    const logoImg = await loadImage(logo)
    const actualWith = Number.parseFloat(logoSize) * qrWidth
    const actualHeight = (actualWith / logoImg.width) * logoImg.height
    const dx = (qrWidth - actualWith) / 2
    const dy = (qrWidth - actualHeight) / 2
    const canvas = await toCanvas(segments, options)
    const ctx = canvas.getContext('2d')
    ctx.fillStyle = options.color?.light || '#fff'
    ctx.roundRect(dx, dy, actualWith, actualHeight, actualWith / 20)
    ctx.fill()
    ctx.drawImage(logoImg, dx, dy, actualWith, actualHeight)
    return canvas.toDataURL()
  }
  const level = options.errorCorrectionLevel ?? 'M'
  options.errorCorrectionLevel =
    level.length === 1 ? level.toUpperCase() : `${level[0].toUpperCase()}${level[1].toLowerCase()}`
  return await toPNG(segments, options)
}
async function loadImage(url) {
  return new Promise((resolve, reject) => {
    const img = new Image()
    img.src = url
    img.crossOrigin = 'anonymous'
    img.onload = () => resolve(img)
    img.onerror = () => reject(/* @__PURE__ */ new Error('Failed to load image'))
  })
}
async function attemptLoadLogo(text, logo, isInternalLink) {
  if (logo) return logo
  if (isInternalLink) return document.querySelector('link[rel="icon"]')?.href
  return ''
}

export {attemptLoadLogo, generateQRCode, loadImage}
